ny:
// RÄTTAD 2026-11-28 (fas 3, f300b-0011): Ramsö och Tynningö stod som stopp före Vaxholm. Ramsö angörs efter
// Vaxholm på linje 4; mellan Strömkajen och Vaxholm går linje 11 till 14 via Nacka strand och Gåshaga brygga.
// KÄLLA: https://kund.printhuset-sthlm.se/wa/w11.pdf — "11A STOCKHOLM – VAXHOLM – BODA – SOLLENKROKA", "Nacka strand", "Gåshaga brygga", "GÄLLER 13 DECEMBER 2026 – 11 APRIL 2027" (läst 2026-11-28)
// KÄLLA: https://kund.printhuset-sthlm.se/wa/h11.pdf — "11A STOCKHOLM – VAXHOLM – GRINDA – BODA – SOLLENKROKA", "GÄLLER 2 APRIL 2026 – 18 JUNI 2026 OCH 17 AUGUSTI 2026 – 12 DECEMBER 2026" (läst 2026-11-28)
// KÄLLA: https://kund.printhuset-sthlm.se/wa/w4.pdf — "Vaxholm avg.", "Ramsö", "Ålstäket", "GÄLLER 13 DECEMBER 2026 – 11 APRIL 2027" (läst 2026-11-28)
// KÄLLA: https://kund.printhuset-sthlm.se/wa/s2.pdf — "2A STOCKHOLM – HÖGANÄS – VAXHOLM", "GÄLLER 19 JUNI 2026 – 16 AUGUSTI 2026" (helår: också h2 och w2) (läst 2026-11-28)
stops: ['Strömkajen', 'Nacka strand', 'Gåshaga brygga', 'Vaxholm'],
operator: 'Waxholmsbolaget',
season: 'Helår',

// RÄTTAD 2026-11-28 (fas 3, f300b-0014, f300b-0015): vintertabellen för linje 11 är publicerad och angör Grinda.
// Sippsö står inte mellan Vaxholm och Lillsved i vintertabellen, så stoppen är de som finns i båda tabellerna.
// KÄLLA: https://kund.printhuset-sthlm.se/wa/w11.pdf — "11A STOCKHOLM – VAXHOLM – BODA – SOLLENKROKA", "GÄLLER 13 DECEMBER 2026 – 11 APRIL 2027", "Lillsved ank.", "Södra Grinda", "Norra Grinda" (läst 2026-11-28)
// KÄLLA: https://kund.printhuset-sthlm.se/wa/h11.pdf — "11A STOCKHOLM – VAXHOLM – GRINDA – BODA – SOLLENKROKA", "GÄLLER 2 APRIL 2026 – 18 JUNI 2026 OCH 17 AUGUSTI 2026 – 12 DECEMBER 2026" (läst 2026-11-28)
stops: ['Strömkajen', 'Vaxholm', 'Lillsved', 'Grinda'],
operator: 'Waxholmsbolaget',
season: 'Tabell 11: hösten till 12 dec 2026, vintern 13 dec 2026 till 11 apr 2027',

// RÄTTAD 2026-11-28 (fas 3, f300b-0019): Ljusterö och Husarö före Finnhamn gäller linje 12, som i vintertabellen
// slutar vid Norra Ingmarsö. I vinter går Strömkajen till Finnhamn med linje 13, via Boda och Svartsö.
// KÄLLA: https://kund.printhuset-sthlm.se/wa/h12.pdf — "12A STOCKHOLM – VAXHOLM – LILLSVED – NORRA INGMARSÖ – HUSARÖ – MÖJA", "Finnhamn" (läst 2026-11-28)
// KÄLLA: https://kund.printhuset-sthlm.se/wa/w12.pdf — "12A STOCKHOLM – LILLSVED – NORRA INGMARSÖ GÄLLER 13/12 – 6/1 OCH 25/3 – 11/4 SAMT ISFRI PERIOD 7/1 – 24/3" (läst 2026-11-28)
// KÄLLA: https://kund.printhuset-sthlm.se/wa/w13.pdf — "13A STOCKHOLM – VAXHOLM – BODA – SÖDRA INGMARSÖ – HUSARÖ", "Finnhamn", "GÄLLER 13 DECEMBER 2026 – 11 APRIL 2027" (läst 2026-11-28)
// KÄLLA: https://kund.printhuset-sthlm.se/wa/s13.pdf — "13A STOCKHOLM – VAXHOLM – BODA – SÖDRA INGMARSÖ – HUSARÖ", "GÄLLER 19 JUNI 2026 – 16 AUGUSTI 2026" (läst 2026-11-28)
stops: ['Strömkajen', 'Vaxholm', 'Finnhamn'],
operator: 'Waxholmsbolaget',
season: 'Helår',

// RÄTTAD 2026-11-28 (fas 3, f300b-0022): Svartsö angörs inte av linje 14 (Sollenkroka till Möja); Svartsö har linje 10, 12 och 13.
// KÄLLA: https://kund.printhuset-sthlm.se/wa/w14.pdf — "14A STOCKHOLM – VAXHOLM – SOLLENKROKA – MÖJA", "Sollenkroka ank.", "Norra Stavsudda", "Berg (Möja)", "GÄLLER 13 DECEMBER 2026 – 11 APRIL 2027" (läst 2026-11-28)
// KÄLLA: https://kund.printhuset-sthlm.se/wa/h14.pdf — "14A STOCKHOLM – VAXHOLM – SOLLENKROKA – MÖJA", "GÄLLER 2 APRIL 2026 – 18 JUNI 2026 OCH 17 AUGUSTI 2026 – 12 DECEMBER 2026" (läst 2026-11-28)
// KÄLLA: https://kund.printhuset-sthlm.se/wa/s14.pdf — "14A STOCKHOLM – VAXHOLM – SOLLENKROKA – MÖJA", "GÄLLER 19 JUNI 2026 – 16 AUGUSTI 2026" (läst 2026-11-28)
stops: ['Sollenkroka', 'Norra Stavsudda', 'Berg (Möja)'],

// RÄTTAD 2026-11-28 (fas 3, f300b-0016): Strömma listar fler bryggor på vägen.
// KÄLLA: https://www.stromma.com/sv-se/stockholm/cinderellabatarna/tidtabeller/ — "1. Strandvägen (Startpunkt)", "2. Nacka Strand", "3. Gåshaga", "4. Vaxholm", "6. Södra Grinda", "7. Gällnö", "8. Eknö", "9. Telegrafholmen" (läst 2026-11-28)
stops: ['Strandvägen', 'Nacka strand', 'Gåshaga', 'Vaxholm', 'Södra Grinda', 'Gällnö', 'Eknö', 'Telegrafholmen', 'Sandhamn'],

// RÄTTAD 2026-11-28 (fas 3, f300b-0002, f300b-0003): kommande avgångar finns bara för Waxholmsbolaget, och listan
// "Båt till öarna" har 58 öar, alltså 53 utöver de fem som nämns (MÄTT: STOCKHOLMSOAR på main 5e0a08d).
description: 'Linjer och bryggor för Waxholmsbolaget och Cinderellabåtarna, kommande avgångar för Waxholmsbolaget och hur du tar båten till Sandhamn, Möja, Finnhamn, Grinda, Utö och ett femtiotal andra öar.',

  url: r.operator === 'Cinderella'
    ? 'https://www.stromma.com/sv-se/stockholm/cinderellabatarna/'
    : 'https://www.waxholmsbolaget.se',
  // RÄTTAD 2026-11-28 (fas 3, f300b-0027): sameAs sa att Waxholmsbolaget är samma organisation som SL. Borttaget för
  // Waxholmsbolaget. Cinderellas sameAs står kvar: cinderellabatarna.com svarade 502 vid läsningen (EJ NÅBAR, f300b-0028).
  ...(r.operator === 'Cinderella' ? { sameAs: 'https://www.cinderellabatarna.com' } : {}),
},
// availability InStock borttaget (f300b-0029): Cinderellabåtarna står som "ÅTER APRIL 2027" hos Strömma.
offers: {
  '@type': 'Offer',
  url: r.infoUrl,
},

// RÄTTAD 2026-11-28 (fas 3, f300b-0037 till f300b-0040): SL-biljett gäller bara i en del av trafiken, och "längre dagsrutter" är obelagt.
// KÄLLA: https://waxholmsbolaget.se/om-oss — "Allt sedan dess har vi trafikerat Stockholms skärgård varenda dag året runt." (läst 2026-11-28)
// KÄLLA: https://waxholmsbolaget.se/biljetter-och-priser/mer-om-biljetter/alla-sl-biljetter-galler-mellan-44-bryggor — "Alla SL-biljetter gäller mellan 44 bryggor i Waxholmsbolagets trafik" (läst 2026-11-28)
// KÄLLA: https://www.stromma.com/sv-se/stockholm/cinderellabatarna/ — "Säsongen löper från slutet av april till slutet av september.", "Ombord finns café och bar med något för alla" (läst 2026-11-28)
acceptedAnswer: { '@type': 'Answer', text: 'Waxholmsbolaget är kollektivtrafiken på vattnet i Stockholms skärgård och går året runt. SL-biljetter gäller mellan 44 bryggor i dess trafik. Cinderellabåtarna drivs av Strömma, går från slutet av april till slutet av september och har café och bar ombord.' },

// RÄTTAD 2026-11-28 (fas 3, f300b-0055): "ca 50 min" stämde inte med tabellen. Restiden är uppmätt i vintertabellen 16
// (13 december 2026 till 11 april 2027), 15 turer Stavsnäs till Sandhamn: 54 till 70 min. Året runt: h16, s16 och w16.
// KÄLLA: https://kund.printhuset-sthlm.se/wa/w16.pdf — "16A STAVSNÄS – SANDHAMN – HAGEDE", "GÄLLER 13 DECEMBER 2026 – 11 APRIL 2027" (läst 2026-11-28)
// KÄLLA: https://kund.printhuset-sthlm.se/wa/s16.pdf — "16A STAVSNÄS – SANDHAMN – HAGEDE", "GÄLLER 19 JUNI 2026 – 16 AUGUSTI 2026" (läst 2026-11-28)
{ name: 'Färja 16', desc: 'Stavsnäs vinterhamn → Sandhamn året runt, 54 till 70 min i vintertabellen från 13 dec 2026' },
// KÄLLA: https://kund.printhuset-sthlm.se/wa/w17.pdf — "17A STAVSNÄS – NÄMDÖ – MÖRTÖ", "GÄLLER 13 DECEMBER 2026 – 11 APRIL 2027" (läst 2026-11-28)
{ name: 'Färja 17-1', desc: 'Stavsnäs vinterhamn → Nämdö' },

// RÄTTAD 2026-11-28 (fas 3, f300b-0060): vägfärjan Vaxholm till Rindö är Trafikverkets Vaxholmsleden, inte Waxholmsbolaget.
// KÄLLA: https://www.trafikverket.se/resa-och-trafik/farjetrafik/vaxholmsleden/ — "Vaxholmsleden går mellan Vaxholm och Rindö i Stockholms skärgård. Färjeledens längd är 970 meter och överfartstiden är sex minuter. Resan med vägfärjan är avgiftsfri." (läst 2026-11-28)
{ name: 'Vaxholmsleden', desc: 'Vaxholm → Rindö, Trafikverkets vägfärja (inte Waxholmsbolaget), sex minuter, avgiftsfri' },
// RÄTTAD 2026-11-28 (P0, fas 3, f300b-0062): varje tur från Räfsnäs till Lidö är beställningstur (märkt b) i höst-,
// vinter- och sommartabellen 2026 utom en sommartur. Restiden uppmätt i w31: 10 till 15 min.
// KÄLLA: https://kund.printhuset-sthlm.se/wa/w31.pdf — "31A RÄFSNÄS – TJOCKÖ – FEJAN", "Beställ resan i SL-appen, på", "08-600 10 00 minst 2 timmar innan", "GÄLLER 13 DECEMBER 2026 – 11 APRIL 2027" (läst 2026-11-28)
// KÄLLA: https://kund.printhuset-sthlm.se/wa/h31.pdf — "31A RÄFSNÄS – TJOCKÖ – FEJAN", "GÄLLER 2 APRIL 2026 – 18 JUNI 2026 OCH 17 AUGUSTI 2026 – 12 DECEMBER 2026" (läst 2026-11-28)
{ name: 'Färja 31-1', desc: 'Räfsnäs brygga → Lidö, 10 till 15 min. Båten angör Lidö bara om du beställt resan i förväg, i SL-appen, på Waxholmsbolagets webb eller på 08-600 10 00' },

// RÄTTAD 2026-11-28 (fas 3, f300b-0066): stoppen var ofullständiga.
// KÄLLA: https://www.stromma.com/sv-se/stockholm/cinderellabatarna/tidtabeller/ — "Hela resan till Sandhamn tar ungefär 2 timmar och 30 minuter.", "2. Nacka Strand", "3. Gåshaga", "6. Södra Grinda", "8. Eknö", "9. Telegrafholmen" (läst 2026-11-28)
// KÄLLA: https://www.stromma.com/sv-se/stockholm/cinderellabatarna/ — "Oavsett om du planerar en dagsutflykt eller vill stanna några dagar är Cinderellabåtarna din naturliga startpunkt." (läst 2026-11-28)
a: 'Cinderellabåtarna går från Strandvägen i Stockholm: inte Strömkajen, som är Waxholmsbolagets kaj. Resan till Sandhamn tar 2 timmar och 30 minuter enligt operatören Strömma, med stopp vid Nacka strand, Gåshaga, Vaxholm, Södra Grinda, Gällnö, Eknö och Telegrafholmen. Dagstur är fullt möjlig. Avgångstiderna finns i Strömmas tidtabell, så vi hänvisar dit i stället för att gissa.',

{/* RÄTTAD 2026-11-28 (fas 3, f300b-0079): vinterns tabeller är publicerade; KÄLLA-raderna i kommentaren överst. */}
Höstens tidtabeller för skärgårdsbåtarna i Stockholm och Göteborg gäller till 12 december.
Vinterns tabeller är publicerade och gäller från 13 december 2026. Länkarna finns nedan.

